import{_ as e,o as t,a as i,a3 as o}from"./chunks/framework.CnT1yzXN.js";const p=JSON.parse('{"title":"Log Analyzer","description":"Smart Minecraft log analyzer. Automatically finds what caused a crash, identifies the mods to blame and suggests solutions.","frontmatter":{"description":"Smart Minecraft log analyzer. Automatically finds what caused a crash, identifies the mods to blame and suggests solutions.","head":[["meta",{"name":"keywords","content":"minecraft crash analyzer, minecraft crash log analyzer, stuzhik, minecraft log analysis, why does minecraft crash, minecraft crash fix"}]]},"headers":[],"relativePath":"en/guide/log-analyzer.md","filePath":"en/guide/log-analyzer.md"}'),l={name:"en/guide/log-analyzer.md"};function n(s,a,r,d,h,c){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="log-analyzer" tabindex="-1">Log Analyzer <a class="header-anchor" href="#log-analyzer" aria-label="Permalink to &quot;Log Analyzer&quot;">​</a></h1><h2 id="automatic-analysis" tabindex="-1">Automatic analysis <a class="header-anchor" href="#automatic-analysis" aria-label="Permalink to &quot;Automatic analysis&quot;">​</a></h2><p>When the game crashes:</p><ol><li>Stuzhik opens the analyzer automatically</li><li>Shows the problems it found</li><li>Possible solutions for each one</li><li>Buttons for automatic fixes (where possible)</li></ol><h2 id="manual-analysis" tabindex="-1">Manual analysis <a class="header-anchor" href="#manual-analysis" aria-label="Permalink to &quot;Manual analysis&quot;">​</a></h2><p>If you need to run the analysis yourself:</p><ol><li>Open the instance</li><li>The &quot;Analyze Logs&quot; button</li><li>Choose the log type: <ul><li><code>crash-report</code> - the latest crash</li><li><code>latest.log</code> - the current session</li><li>Pick a file manually</li></ul></li></ol><h2 id="problem-types" tabindex="-1">Problem types <a class="header-anchor" href="#problem-types" aria-label="Permalink to &quot;Problem types&quot;">​</a></h2><h3 id="critical" tabindex="-1">Critical <a class="header-anchor" href="#critical" aria-label="Permalink to &quot;Critical&quot;">​</a></h3><p>Block the launch completely:</p><table tabindex="0"><thead><tr><th>Problem</th><th>Cause</th><th>Solution</th></tr></thead><tbody><tr><td>Java version mismatch</td><td>Wrong Java version</td><td>Stuzhik installs the right one</td></tr><tr><td>Missing dependency</td><td>A required mod is missing</td><td>Automatic install</td></tr><tr><td>Mod conflict</td><td>Incompatible mods</td><td>Remove one of the mods</td></tr></tbody></table><h3 id="high" tabindex="-1">High <a class="header-anchor" href="#high" aria-label="Permalink to &quot;High&quot;">​</a></h3><p>Cause a crash during play:</p><ul><li>OutOfMemoryError</li><li>Mixin conflicts</li><li>ClassNotFoundException</li><li>NullPointerException in a mod</li></ul><h3 id="medium" tabindex="-1">Medium <a class="header-anchor" href="#medium" aria-label="Permalink to &quot;Medium&quot;">​</a></h3><p>Can cause problems:</p><ul><li>Deprecated warnings</li><li>Config errors</li><li>Missing textures/models</li></ul><h3 id="low" tabindex="-1">Low <a class="header-anchor" href="#low" aria-label="Permalink to &quot;Low&quot;">​</a></h3><p>Don&#39;t affect the game:</p><ul><li>Info messages</li><li>Debug logs</li><li>Performance warnings</li></ul><h2 id="solutions" tabindex="-1">Solutions <a class="header-anchor" href="#solutions" aria-label="Permalink to &quot;Solutions {#solutions}&quot;">​</a></h2><h3 id="automatic" tabindex="-1">Automatic <a class="header-anchor" href="#automatic" aria-label="Permalink to &quot;Automatic&quot;">​</a></h3><p>The &quot;Apply&quot; button for:</p><p><strong>Removing a mod:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>Remove problematic_mod.jar</span></span></code></pre></div><p><strong>Increasing memory:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>Was: 2GB → Now: 4GB</span></span></code></pre></div><p><strong>Installing a dependency:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>Install fabric-api-0.92.0.jar</span></span></code></pre></div><p><strong>Changing a config:</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>config/mod.toml: option = false → true</span></span></code></pre></div><h3 id="manual" tabindex="-1">Manual <a class="header-anchor" href="#manual" aria-label="Permalink to &quot;Manual&quot;">​</a></h3><p>Step-by-step instructions:</p><ol><li>Download mod X, version Y</li><li>Delete the old version</li><li>Put the new one in mods/</li><li>Restart</li></ol><h2 id="live-monitoring" tabindex="-1">Live monitoring <a class="header-anchor" href="#live-monitoring" aria-label="Permalink to &quot;Live monitoring {#live-monitoring}&quot;">​</a></h2><h3 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h3><ol><li>Launch the instance</li><li>Stuzhik starts monitoring automatically</li><li>An indicator in the header shows the status</li></ol><h3 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h3><p><strong>Warning:</strong> Warnings from the log</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>[Sodium] Incompatible mixin detected</span></span></code></pre></div><p><strong>Error:</strong> Errors that don&#39;t crash the game</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>[KubeJS] Script error in startup.js:15</span></span></code></pre></div><p><strong>Crash:</strong> A full crash</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>Game crashed! Analyzing...</span></span></code></pre></div><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><p>When a problem is detected:</p><ol><li>A pop-up notification</li><li>A list of problems in the live panel</li><li>Buttons to fix them</li></ol><h2 id="knowledge-base" tabindex="-1">Knowledge base <a class="header-anchor" href="#knowledge-base" aria-label="Permalink to &quot;Knowledge base&quot;">​</a></h2><h3 id="learning" tabindex="-1">Learning <a class="header-anchor" href="#learning" aria-label="Permalink to &quot;Learning&quot;">​</a></h3><p>When you apply a solution:</p><ol><li>Stuzhik saves the result</li><li>&quot;Helped&quot; / &quot;Didn&#39;t help&quot;</li><li>The success rate is updated</li></ol><h3 id="personalization" tabindex="-1">Personalization <a class="header-anchor" href="#personalization" aria-label="Permalink to &quot;Personalization&quot;">​</a></h3><p>Solutions are ranked:</p><table tabindex="0"><thead><tr><th>Solution</th><th>Success Rate</th><th>Shown</th></tr></thead><tbody><tr><td>Remove mod</td><td>95%</td><td>✅ First</td></tr><tr><td>Update</td><td>70%</td><td>✅ Second</td></tr><tr><td>Change config</td><td>30%</td><td>⚠️ With a warning</td></tr></tbody></table><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><h3 id="for-a-report" tabindex="-1">For a report <a class="header-anchor" href="#for-a-report" aria-label="Permalink to &quot;For a report&quot;">​</a></h3><p>The analyzer&#39;s buttons after an analysis:</p><ul><li>&quot;Export&quot; — the analysis report as <code>.json</code> (you can open it again with the &quot;Import&quot; button)</li><li>&quot;Copy as Markdown&quot; — the report to the clipboard, to paste into a chat or on GitHub</li></ul><h3 id="for-support" tabindex="-1">For support <a class="header-anchor" href="#for-support" aria-label="Permalink to &quot;For support&quot;">​</a></h3><p>When you contact a mod&#39;s author:</p><ol><li>The &quot;Archive&quot; button (available for an instance) — saves a <code>.zip</code></li><li>It includes: <ul><li><code>latest.log</code> and the end of <code>debug.log</code></li><li>The latest crash reports (up to 5)</li><li>Stuzhik&#39;s analysis</li><li>The instance name</li></ul></li><li>Attach it in <a href="https://t.me/stuzhik_launcher" target="_blank" rel="noreferrer">Telegram</a> (in Russian)</li></ol><h2 id="error-patterns" tabindex="-1">Error patterns <a class="header-anchor" href="#error-patterns" aria-label="Permalink to &quot;Error patterns&quot;">​</a></h2><p>Stuzhik recognizes ~50 types of errors:</p><h3 id="java" tabindex="-1">Java <a class="header-anchor" href="#java" aria-label="Permalink to &quot;Java&quot;">​</a></h3><ul><li>OutOfMemoryError</li><li>StackOverflowError</li><li>UnsupportedClassVersionError</li><li>NoClassDefFoundError</li></ul><h3 id="minecraft" tabindex="-1">Minecraft <a class="header-anchor" href="#minecraft" aria-label="Permalink to &quot;Minecraft&quot;">​</a></h3><ul><li>Missing registry entries</li><li>Invalid block states</li><li>Corrupted chunk data</li><li>Missing textures</li></ul><h3 id="mods" tabindex="-1">Mods <a class="header-anchor" href="#mods" aria-label="Permalink to &quot;Mods&quot;">​</a></h3><ul><li>Mixin conflicts</li><li>ASM transformation failures</li><li>Config parsing errors</li><li>Dependency issues</li></ul><h3 id="loaders" tabindex="-1">Loaders <a class="header-anchor" href="#loaders" aria-label="Permalink to &quot;Loaders&quot;">​</a></h3><ul><li>Forge mod on Fabric</li><li>Missing Fabric API</li><li>Incompatible loader version</li></ul>',71)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
